// The contract states that `derive` and `watch` run their first argument, on
// every call and during it, as the tracked compute of a memo or an effect the
// call creates; that `deriveMaybe` may; and that `deriveWrapped` runs its
// argument tracked, with no owner claim.
//
// The signatures are `tsc`-clean on purpose: every call in `App.tsx` is well
// typed, so whatever the checker reports here is nothing `tsc` reports.
export declare function derive(fn: () => unknown): void;
export declare function deriveMaybe(flag: boolean, fn: () => unknown): void;
export declare function deriveWrapped(fn: () => unknown): void;
export declare function watch(compute: () => unknown, effect: (value: unknown) => void): void;
